import {blank,clone,uid,validateImport} from './model.mjs';
export function validateLibrary(raw){if(!raw||raw.schema!=='catastrophe-library'||raw.version!==1||!Array.isArray(raw.items)||raw.items.length>100)throw Error('Arquivo de biblioteca incompatível (máximo de 100 itens).');if(JSON.stringify(raw).length>80000000)throw Error('Biblioteca excede 80 MB.');const items=[];for(const item of raw.items){if(!item||!['component','template','style','content'].includes(item.kind)||typeof item.name!=='string'||item.name.length>400)throw Error('Item de biblioteca inválido.');if(item.kind==='content'&&(!['ability','ritual','weapon','equipment'].includes(item.contentKind)||typeof item.body!=='string'||item.body.length>100000))throw Error('Conteúdo reutilizável inválido.');const doc=blank();doc.blocks=['style','content'].includes(item.kind)?[]:item.blocks;doc.groups=item.groups||[];if(!Array.isArray(doc.blocks)||!doc.blocks.length&&!['style','content'].includes(item.kind))throw Error('Composição sem elementos.');for(const k of ['theme','fonts','background','accent','showFrame','guides','pageHeight'])if(item[k]!==undefined)doc[k]=clone(item[k]);if(item.contentData){const content={...doc,...clone(item.contentData)};validateImport(content);}doc.libraryItem=item;validateImport(doc);for(const b of doc.blocks){if(b.dataBinding){const desc=b.dataBinding;if(!['ability','ritual'].includes(desc.kind)||typeof desc.label!=='string'||typeof desc.key!=='string'||JSON.stringify(desc).length>5000)throw Error('Vínculo de biblioteca inválido.');}}items.push(clone(item));}return {schema:'catastrophe-library',version:1,items};}
export async function exportLibrary(items,imageData,availableFonts=[]){const result=clone(items);for(const item of result)if(!item.fonts){const serialized=JSON.stringify(item);item.fonts=availableFonts.filter(f=>serialized.includes(f.family)).map(clone);}for(const item of result)for(const b of item.blocks||[])if(b.image)b.image=await imageData(b.image);return validateLibrary({schema:'catastrophe-library',version:1,items:result});}
export function mergeLibrary(existing,imported){const validated=validateLibrary(imported);if(existing.length+validated.items.length>100)throw Error('A importação excederia 100 itens; a biblioteca atual foi preservada.');const additions=validated.items.map(item=>({...item,id:uid(),name:existing.some(i=>i.name===item.name)?item.name+' (importado)':item.name}));return {items:[...existing,...additions],additions};}
export function writeLibraryBatch(db,items){return new Promise((resolve,reject)=>{const t=db.transaction('library','readwrite'),store=t.objectStore('library');for(const item of items)store.put(item);t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('Importação interrompida; nenhum item foi adicionado.'));});}
